/* ============================================
   TOOLTIP COMPONENT
   Contextual text label on hover / focus
   ============================================ */

.ds-tooltip {
  position: relative;
  display: inline-flex;
}

/* ============================================
   PANEL
   ============================================ */

/* Placed by the shared anchored-position behaviour
   (src/behaviors/useAnchoredPosition.ts), which makes the panel fixed and
   sets where it sits, so a scroll container around the trigger (a bordered
   table's wrapper, a rail) cannot clip it. The panel keeps its place in the
   DOM, so it stacks inside the trigger's own context at the floating layer.
   The side it lands on, after any flip, is its data-side. */
.ds-tooltip__panel {
  z-index: var(--layer-floating);
  padding: var(--padding-150) var(--padding-200); /* 6px 8px */
  border-radius: var(--radius-100); /* 4px */
  /* The floating surface, same recipe as Popover: page background (the
     container fill is semi-transparent), hairline border, floating shadow.
     Same-polarity in both themes — light bubble on light, dark on dark —
     softer than the old inverse fill. */
  border: var(--border-025) solid var(--color-bg-container-border);
  background-color: var(--color-bg-page-primary);
  color: var(--color-text-primary);
  box-shadow: var(--shadow-floating);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  white-space: nowrap;
  pointer-events: none;
  /* Hidden panels leave layout entirely, so they are never measured or
     placed. display transitions discretely (allow-discrete holds it through
     the exit fade; the entry fade starts from @starting-style below);
     browsers without those skip the fades but show and hide correctly. */
  display: none;
  opacity: 0;
  transition-property: opacity, transform, display;
  transition-duration: var(--motion-duration-fast);
  transition-timing-function: var(--motion-ease-standard);
  transition-behavior: allow-discrete;
}

.ds-tooltip__panel--visible {
  display: block;
  opacity: 1;
}

/* ============================================
   POSITIONS
   The behaviour sets where the panel sits; each side only slides in from
   that side, keyed on data-side so a flipped panel slides the right way.
   ============================================ */

.ds-tooltip__panel[data-side='top'] {
  transform: translateY(4px);
}

.ds-tooltip__panel[data-side='top'].ds-tooltip__panel--visible {
  transform: translateY(0);
}

.ds-tooltip__panel[data-side='bottom'] {
  transform: translateY(-4px);
}

.ds-tooltip__panel[data-side='bottom'].ds-tooltip__panel--visible {
  transform: translateY(0);
}

.ds-tooltip__panel[data-side='left'] {
  transform: translateX(4px);
}

.ds-tooltip__panel[data-side='left'].ds-tooltip__panel--visible {
  transform: translateX(0);
}

.ds-tooltip__panel[data-side='right'] {
  transform: translateX(-4px);
}

.ds-tooltip__panel[data-side='right'].ds-tooltip__panel--visible {
  transform: translateX(0);
}

/* Entry states for the display flip: a panel arriving from display:none has
   no prior computed style, so these supply the fade's starting frame. Each
   mirrors its position's hidden transform above. */
@starting-style {
  .ds-tooltip__panel[data-side='top'].ds-tooltip__panel--visible {
    opacity: 0;
    transform: translateY(4px);
  }

  .ds-tooltip__panel[data-side='bottom'].ds-tooltip__panel--visible {
    opacity: 0;
    transform: translateY(-4px);
  }

  .ds-tooltip__panel[data-side='left'].ds-tooltip__panel--visible {
    opacity: 0;
    transform: translateX(4px);
  }

  .ds-tooltip__panel[data-side='right'].ds-tooltip__panel--visible {
    opacity: 0;
    transform: translateX(-4px);
  }
}

/* ============================================
   ARROW
   ============================================ */

/* The arrow is a rotated square in the panel's fill. It overlaps the panel
   by a pixel more than before so its opaque fill covers the panel border
   behind it, and draws the hairline itself on its two outward edges only.
   --ds-tooltip-arrow is where along the bubble the trigger's centre falls,
   written by the component; it is the midpoint until a clamp moves the
   bubble off the trigger. */
.ds-tooltip__arrow {
  position: absolute;
  width: 8px;
  height: 8px;
  background-color: var(--color-bg-page-primary);
  transform: rotate(45deg);
}

/* Arrow — top position (arrow points down) */
.ds-tooltip__panel[data-side='top'] .ds-tooltip__arrow {
  bottom: -5px;
  left: var(--ds-tooltip-arrow, 50%);
  margin-left: -4px; /* ds-allow(spacing): half the 8px arrow, centring it on the panel edge */
  border-right: var(--border-025) solid var(--color-bg-container-border);
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
}

/* Arrow — bottom position (arrow points up) */
.ds-tooltip__panel[data-side='bottom'] .ds-tooltip__arrow {
  top: -5px;
  left: var(--ds-tooltip-arrow, 50%);
  margin-left: -4px; /* ds-allow(spacing): half the 8px arrow */
  border-top: var(--border-025) solid var(--color-bg-container-border);
  border-left: var(--border-025) solid var(--color-bg-container-border);
}

/* Arrow — left position (arrow points right) */
.ds-tooltip__panel[data-side='left'] .ds-tooltip__arrow {
  right: -5px;
  top: var(--ds-tooltip-arrow, 50%);
  margin-top: -4px; /* ds-allow(spacing): half the 8px arrow */
  border-top: var(--border-025) solid var(--color-bg-container-border);
  border-right: var(--border-025) solid var(--color-bg-container-border);
}

/* Arrow — right position (arrow points left) */
.ds-tooltip__panel[data-side='right'] .ds-tooltip__arrow {
  left: -5px;
  top: var(--ds-tooltip-arrow, 50%);
  margin-top: -4px; /* ds-allow(spacing): half the 8px arrow */
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
  border-left: var(--border-025) solid var(--color-bg-container-border);
}

'use client';

import React, {
  useState,
  useEffect,
  useRef,
  useId,
  cloneElement,
  isValidElement,
  type ReactNode,
  type ReactElement,
} from 'react';
import { useLayer } from '../../behaviors/useLayer';
import { useAnchoredPosition } from '../../behaviors/useAnchoredPosition';
import './Tooltip.css';
import { MOTION_HOVER_SHOW_DELAY_MS, MOTION_HOVER_HIDE_DELAY_MS } from '../../tokens/motion';

type TooltipOwnProps = {
  /** Trigger element */
  children?: ReactNode;
  /**
   * Tooltip text content. Replaces the native `content` attribute, which only
   * means something on a `<meta>` element.
   */
  content: string;
  /** Preferred position */
  position?: 'top' | 'bottom' | 'left' | 'right';
  /** Delay before showing (in ms) */
  showDelay?: number;
  /** Delay before hiding (in ms) */
  hideDelay?: number;
  /** Additional CSS classes */
  className?: string;
};

export interface TooltipProps
  extends TooltipOwnProps,
    Omit<React.ComponentPropsWithoutRef<'span'>, keyof TooltipOwnProps> {}

const clamp = (value: number, min: number, max: number) =>
  max < min ? min : Math.min(Math.max(value, min), max);

/**
 * Tooltip component for contextual text labels.
 * Appears on hover or focus with a short delay.
 * Rides the system's floating surface — page background, hairline border,
 * floating shadow — so the bubble stays light in light theme and dark in dark.
 *
 * The panel stays in the trigger's DOM position (so it keeps the trigger's
 * stacking context and any theme scoped above it) but is `position: fixed`,
 * placed from the trigger's rectangle each time it shows and again on scroll
 * and resize while visible. That is what lets a tooltip inside a scroll
 * container — a bordered table's wrapper, a rail — show whole instead of
 * being clipped at the container's edge. The panel is clamped inside the box
 * it is placed from (the viewport, or the transformed or blurred ancestor
 * that positions it), and the arrow slides along the bubble to stay on the
 * trigger's centre when the clamp moves the bubble off it.
 *
 * A visible tooltip is a layer on the shared dismissal stack
 * (src/behaviors/useLayer): Escape hides it wherever focus is (WCAG 1.4.13),
 * and hides only it, so inside a Dialog the first Escape clears the tooltip
 * and the second closes the Dialog.
 */
export const Tooltip = React.forwardRef<HTMLSpanElement, TooltipProps>(
  (
    {
      children,
      content,
      position = 'top',
      showDelay = MOTION_HOVER_SHOW_DELAY_MS,
      hideDelay = MOTION_HOVER_HIDE_DELAY_MS,
      className = '',
      onMouseEnter,
      onMouseLeave,
      onFocus,
      onBlur,
      ...rest
    },
    ref,
  ) => {
    const [visible, setVisible] = useState(false);
    const showTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);
    const hideTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);
    const anchorRef = useRef<HTMLSpanElement | null>(null);
    const panelRef = useRef<HTMLSpanElement | null>(null);
    const tooltipId = useId();

    const baseClass = 'ds-tooltip';

    const setRefs = (node: HTMLSpanElement | null) => {
      anchorRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    const show = () => {
      clearTimeout(hideTimeoutRef.current);
      showTimeoutRef.current = setTimeout(() => setVisible(true), showDelay);
    };

    const hide = () => {
      clearTimeout(showTimeoutRef.current);
      hideTimeoutRef.current = setTimeout(() => setVisible(false), hideDelay);
    };

    useEffect(() => {
      return () => {
        clearTimeout(showTimeoutRef.current);
        clearTimeout(hideTimeoutRef.current);
      };
    }, []);

    useLayer({
      open: visible,
      onDismiss: () => {
        clearTimeout(showTimeoutRef.current);
        clearTimeout(hideTimeoutRef.current);
        setVisible(false);
      },
    });

    // Placement writes straight onto the panel rather than through state
    // (src/behaviors/useAnchoredPosition): it runs before paint, so the bubble
    // never shows at a stale position, and a scroll or resize costs no render.
    // The arrow follows the trigger's centre along the bubble, held clear of
    // the bubble's corners by twice the gap (half the arrow plus the corner
    // radius).
    useAnchoredPosition({
      open: visible,
      anchorRef,
      panelRef,
      side: position,
      align: 'center',
      gapProperty: '--gap-100',
      onPlace: ({ side, x, y, width, height, anchor }) => {
        const panel = panelRef.current;
        if (!panel) return;
        const gap = parseFloat(getComputedStyle(panel).getPropertyValue('--gap-100')) || 0;
        const inset = gap * 2;
        const arrow =
          side === 'left' || side === 'right'
            ? clamp(anchor.top + anchor.height / 2 - y, inset, height - inset)
            : clamp(anchor.left + anchor.width / 2 - x, inset, width - inset);
        panel.style.setProperty('--ds-tooltip-arrow', `${arrow}px`);
      },
    });

    // Associate the trigger with the tooltip for screen readers. When the
    // child is a single element, put aria-describedby directly on it.
    const trigger = isValidElement(children)
      ? cloneElement(children as ReactElement<{ 'aria-describedby'?: string }>, {
          'aria-describedby': tooltipId,
        })
      : children;

    const containerClasses = [baseClass, className].filter(Boolean).join(' ');
    const panelClasses = [
      `${baseClass}__panel`,
      `${baseClass}__panel--${position}`,
      visible ? `${baseClass}__panel--visible` : '',
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <span
        {...rest}
        ref={setRefs}
        className={containerClasses}
        onMouseEnter={(event) => {
          onMouseEnter?.(event);
          show();
        }}
        onMouseLeave={(event) => {
          onMouseLeave?.(event);
          hide();
        }}
        onFocus={(event) => {
          onFocus?.(event);
          show();
        }}
        onBlur={(event) => {
          onBlur?.(event);
          hide();
        }}
      >
        {trigger}

        {/*
          No aria-hidden toggle: the trigger's aria-describedby points here, and
          show is delayed, so the description must be computable the moment
          focus lands. The panel hides with display:none (accessible-name
          computation includes hidden nodes referenced by IDREF, so the
          description survives), so a hidden panel is never measured or placed.
        */}
        <span ref={panelRef} className={panelClasses} role="tooltip" id={tooltipId}>
          {content}
          <span className={`${baseClass}__arrow`} />
        </span>
      </span>
    );
  },
);

Tooltip.displayName = 'Tooltip';
